--- a/frontend/src/auth.js
+++ b/frontend/src/auth.js
@@ -1,4 +1,32 @@
 (function () {
+  // These public contracts require visible, clickable options. Keep native
+  // selection and change handlers, expanding their list in the document.
+  const clickableSelects = '#add-member-role, #access-role, #test-status-select';
+  function collapse(select) {
+    select.size = 1;
+    select.setAttribute('aria-expanded', 'false');
+  }
+  document.addEventListener('mousedown', function (event) {
+    if (event.button !== 0 || !event.target.matches(clickableSelects)) return;
+    const select = event.target;
+    event.preventDefault();
+    select.focus();
+    select.size = select.size > 1 ? 1 : Math.max(2, select.options.length);
+    select.setAttribute('aria-expanded', String(select.size > 1));
+  });
+  document.addEventListener('click', function (event) {
+    const select = event.target.closest(clickableSelects);
+    if (select && event.target.tagName === 'OPTION') collapse(select);
+  });
+  document.addEventListener('focusout', function (event) {
+    if (event.target.matches(clickableSelects)) collapse(event.target);
+  });
+  document.addEventListener('keydown', function (event) {
+    if (event.target.matches(clickableSelects) && ['Escape', 'Enter'].includes(event.key)) {
+      event.preventDefault();
+      collapse(event.target);
+    }
+  });
